<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\UserInvitation\Application\Usecase\Resend;

use DateTimeImmutable;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Access\User\Domain\Gateway\UserReadGateway;
use Civi\Lughauth\Features\Access\UserInvitation\Domain\UserInvitationStatusOptions;
use Civi\Lughauth\Features\Access\UserInvitation\Domain\Gateway\UserInvitationWriteGateway;
use Civi\Lughauth\Features\Oidc\UserInvitation\Domain\Gateway\UserInvitationMailGateway;

class InvitationResendUsecase
{
    public function __construct(
        private readonly UserInvitationWriteGateway $writeGateway,
        private readonly UserInvitationMailGateway $mailer,
        private readonly UserReadGateway $users,
        private readonly string $baseUrl,
    ) {
    }

    public function resend(string $uid, string $tenantName): void
    {
        $invitation = $this->writeGateway->findOneForUpdateByUid($uid);
        if ($invitation === null) {
            throw new \DomainException('Invitation not found.');
        }
        if ($invitation->getStatus() !== UserInvitationStatusOptions::PENDING) {
            throw new \DomainException('Only pending invitations can be resent.');
        }

        $tenantRef    = $invitation->getTenant();
        $inviterUid   = $invitation->getInvitedBy()->uid() ?? '';
        $inviterEmail = '';

        if ($inviterUid !== '') {
            $inviter      = $this->users->findOneByUid($inviterUid);
            $inviterEmail = $inviter?->getEmail() ?? '';
        }

        $rawToken  = bin2hex(random_bytes(32));
        $tokenHash = hash('sha256', $rawToken);
        $expiresAt = new DateTimeImmutable('+7 days');

        $attrs = $invitation->toAttributes()
            ->tokenHash($tokenHash)
            ->expiredAt($expiresAt);
        $this->writeGateway->update($invitation, $invitation->update($attrs));

        $tenantId  = $tenantRef->uid() ?? '';
        $acceptUrl = rtrim($this->baseUrl, '/') . '/oauth/openid/' . urlencode($tenantName)
            . '/invitation/accept?token=' . urlencode($rawToken);

        $this->mailer->sendInvitation(
            toEmail: $invitation->getEmail(),
            tenant: new TenantRef($tenantId),
            acceptUrl: $acceptUrl,
            invitedByEmail: $inviterEmail,
            expiresAt: $expiresAt,
        );
    }
}
